    export const getDocumentsCompleteUploadUrl = (documentId: string,
    versionNo: number,) => {




  return `/api/v1/documents/${documentId}/versions/${versionNo}/complete`
}

/**
 * Verify the uploaded bytes (size, type sniffing, SHA-256) and make the version current.
 * @summary Complete Upload
 */
export const documentsCompleteUpload = async (documentId: string,
    versionNo: number, options?: Parameters<typeof apiFetch>[1]): Promise<DocumentOut> => {

  return apiFetch<DocumentOut>(getDocumentsCompleteUploadUrl(documentId,versionNo),
  {
    ...options,
    method: 'POST'


  }
);}





